public class DoctorPrescription : Item
{
	public static string staticID = "DoctorPrescription";

	private NumVarStatMod healMod;

	protected override string ExtraInfo => PercentToStr(healMod, "+");

	public DoctorPrescription()
	{
		ID = staticID;
		category = Category.Defense;
		combineOnly = true;
		healMod = new NumVarStatMod(ID, 0.5f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (parentEntity != null)
		{
			parentEntity.health.healModifierStat.Modify(healMod, givenStatus);
		}
	}
}
=== ./DoctorVial.cs
using System;
using UnityEngine;

public class DoctorVial : Item
{
	public static string staticID = "DoctorVial";

	private float healPercentage = 0.1f;

	public DoctorVial()
	{
		ID = staticID;
		category = Category.Defense;
		combineOnly = true;
	}

	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		LoadingScreen loadingScreen = GameController.loadingScreen;
		loadingScreen.loadCompleteEventHandlers = (LoadingScreen.LoadCompleteEvent)Delegate.Remove(loadingScreen.loadCompleteEventHandlers, new LoadingScreen.LoadCompleteEvent(OnLoadComplete));
		if (givenStatus)
		{
			LoadingScreen loadingScreen2 = GameController.loadingScreen;
			loadingScreen2.loadCompleteEventHandlers = (LoadingScreen.LoadCompleteEvent)Delegate.Combine(loadingScreen2.loadCompleteEventHandlers, new LoadingScreen.LoadCompleteEvent(OnLoadComplete));
		}
	}

	private void OnLoadComplete()
	{
		if (!(parentEntity == null) && !(parentEntity.health == null))
		{
			parentEntity.health.RestoreHealth(Mathf.CeilToInt(healPercentage * parentEntity.health.healthStat.ModifiedValue));
		}
	}
}
