using System;

public class DotEventItem : Item
{
	public bool activateOnApply;

	public bool activateOnRemove;

	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	public virtual void SetEventHandlers(bool givenStatus)
	{
		if (!SetParentAsPlayer() || parentPlayer.dotManager == null)
		{
			return;
		}
		Player player = parentPlayer;
		player.statusApplyEventHandlers = (Entity.StatusEffectEventHandler)Delegate.Remove(player.statusApplyEventHandlers, new Entity.StatusEffectEventHandler(OnDotApply));
		Player player2 = parentPlayer;
		player2.statusRemoveEventHandlers = (Entity.StatusEffectEventHandler)Delegate.Remove(player2.statusRemoveEventHandlers, new Entity.StatusEffectEventHandler(OnDotRemove));
		if (givenStatus)
		{
			if (activateOnApply)
			{
				Player player3 = parentPlayer;
				player3.statusApplyEventHandlers = (Entity.StatusEffectEventHandler)Delegate.Combine(player3.statusApplyEventHandlers, new Entity.StatusEffectEventHandler(OnDotApply));
			}
			if (activateOnRemove)
			{
				Player player4 = parentPlayer;
				player4.statusRemoveEventHandlers = (Entity.StatusEffectEventHandler)Delegate.Combine(player4.statusRemoveEventHandlers, new Entity.StatusEffectEventHandler(OnDotRemove));
			}
		}
	}

	public virtual void OnDotApply(ElementType givenElement)
	{
	}

	public virtual void OnDotRemove(ElementType givenElement)
	{
	}
}
