public class DoubleToil : Item
{
	public static string staticID = "DoubleToil";

	private NumVarStatMod damageMod;

	private NumVarStatMod cdMod;

	public DoubleToil()
	{
		ID = staticID;
		category = Category.Misc;
		isCursed = true;
		damageMod = new NumVarStatMod(ID, 1f, 10, VarStatModType.Multiplicative);
		cdMod = new NumVarStatMod(ID, -0.5f, 10, VarStatModType.Multiplicative);
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (!(parentEntity == null))
		{
			parentEntity.health.damageTakenStat.Modify(damageMod, givenStatus);
			StatManager.ModifyAllStatData(cdMod, parentSkillCategory, "cooldown", IgnoreStatusConditional, givenStatus);
		}
	}
}
