using System.Collections.Generic;

public class DoubleTrouble : Item
{
	public static string staticID = "DoubleTrouble";

	private NumVarStatMod damageMod;

	private Dictionary<string, NumVarStatMod> modDict;

	public DoubleTrouble()
	{
		ID = staticID;
		category = Category.Offense;
		isCursed = true;
		damageMod = new NumVarStatMod(ID, 1f, 10, VarStatModType.Multiplicative);
		modDict = new Dictionary<string, NumVarStatMod>
		{
			{ "damage", damageMod },
			{
				"overdriveProgressMultiplier",
				new NumVarStatMod(ID, -0.5f, 10, VarStatModType.Multiplicative)
			}
		};
	}

	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}

	private void SetModStatus(bool givenStatus)
	{
		if (!(parentEntity == null))
		{
			parentEntity.health.damageTakenStat.Modify(damageMod, givenStatus);
			StatManager.ModifyAllStatData(modDict, parentSkillCategory, IgnoreStatusConditional, givenStatus);
		}
	}
