public class ElementalResistanceWithArcana : Item
{
	public static string staticID = "ElementalResistanceWithArcana";
	private float resPerCount = -0.05f;
	private float minResValue = -0.09f;
	private bool modStatus;
	private bool itemStatus;
	private Dictionary<ElementType, NumVarStatMod> eleModDict = new Dictionary<ElementType, NumVarStatMod>();
	public ElementalResistanceWithArcana()
	{
		ID = staticID;
		category = Category.Defense;
	}
	public override void Activate()
	{
		UpdateItemBar(ItemStatusBar.ItemState.Disabled);
		SetEventHandlers(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
		RemoveFromItemBar();
	}
	private void SetEventHandlers(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			SetModStatus(givenStatus);
			Player player = parentPlayer;
			Player player2 = parentPlayer;
			Player player3 = parentPlayer;
			if (givenStatus)
			{
				Player player4 = parentPlayer;
				Player player5 = parentPlayer;
				Player player6 = parentPlayer;
			}
		}
	}
	private void OnSkillChange(Player.SkillState givenSkill)
	{
		SetModStatus(givenStatus: true);
	}
	private void OnSkillAssign(Player.SkillState givenSkill, int givenSlot)
	{
		SetModStatus(givenStatus: true);
	}
	private void SetModStatus(bool givenStatus)
	{
		if (!(parentPlayer == null))
		{
			if (givenStatus)
			{
				CalculateModValues();
			}
			ApplyMod(givenStatus);
		}
	}
	private void CalculateModValues()
	{
		foreach (NumVarStatMod value in eleModDict.Values)
		{
			value.modValue = 0f;
		}
		for (int i = 0; i < parentPlayer.assignedSkills.Length; i++)
		{
			if (parentPlayer.assignedSkills[i] != null)
			{
				UpdateModDict(parentPlayer.assignedSkills[i].element);
			}
		}
		if (parentPlayer.stockSkill != null)
		{
			UpdateModDict(parentPlayer.stockSkill.element);
		}
	}
	private void ApplyMod(bool givenStatus)
	{
		itemStatus = false;
		foreach (KeyValuePair<ElementType, NumVarStatMod> item in eleModDict)
		{
			modStatus = givenStatus && ModIsValid(item.Value);
			parentPlayer.health.elemModDict[item.Key].Modify(item.Value, modStatus);
			parentPlayer.health.statusResDict[item.Key].Modify(item.Value, modStatus);
			if (!itemStatus)
			{
				itemStatus = modStatus;
			}
		}
		UpdateItemBar(itemStatus ? ItemStatusBar.ItemState.Active : ItemStatusBar.ItemState.Disabled);
	}
	private void UpdateModDict(ElementType givenElement)
	{
		if (!eleModDict.ContainsKey(givenElement))
		{
			eleModDict[givenElement] = new NumVarStatMod(ID, 0f, 10, VarStatModType.Multiplicative);
		}
		eleModDict[givenElement].modValue += resPerCount;
	}
	private bool ModIsValid(NumVarStatMod givenMod)
	{
		return givenMod != null && givenMod.modValue <= minResValue;
	}
}
