	{
		if (!SetParentAsPlayer())
		{
			return;
		}
		Player player = parentPlayer;
		Player player2 = parentPlayer;
		Player player3 = parentPlayer;
		Player player4 = parentPlayer;
		if (givenStatus)
		{
			Player player5 = parentPlayer;
			Player player6 = parentPlayer;
			Player player7 = parentPlayer;
			Player player8 = parentPlayer;
		}
		Player.SkillState[] assignedSkills = parentPlayer.assignedSkills;
		foreach (Player.SkillState givenSkill in assignedSkills)
		{
			if (SetEmpStatus(givenSkill, givenStatus))
			{
				break;
			}
		}
		StatManager.ModifyAllStatData(cdMod, parentSkillCategory, "cooldown", IsDashConditional, givenStatus);
